const config = $('⚙️ Config Growth54').item.json;
const empresaRaw = $('📊 Obtener Perfil Empresa').item?.json || {};
const estRaw = $('🎯 Obtener Estrategia G54').item?.json || {};
const postsRaw = $('📝 Obtener Posts Publicados G54').item?.json || {};
const leadsRaw = $('💼 Obtener Leads G54').item?.json || {};
const metricasRaw = $('📈 Obtener Métricas G54').item?.json || {};
let fbInsights = {};
try { fbInsights = $('📊 Graph API: FB Insights').item?.json || {}; } catch(e) {}
let igInsights = {};
try { igInsights = $('📊 Graph API: IG Insights').item?.json || {}; } catch(e) {}

const empresa = empresaRaw.data || {};
const estrategia = estRaw.data || {};
const posts = postsRaw.data || [];
const leads = leadsRaw.data || [];
const metricas = metricasRaw.data || [];
const fbPosts = fbInsights.data || [];
const igMedia = igInsights.data || [];

// Leads stats
const totalLeads = leads.length;
const leadsCalientes = leads.filter(l => (l.clasificacion || '').toLowerCase() === 'caliente').length;
const leadsTibios = leads.filter(l => (l.clasificacion || '').toLowerCase() === 'tibio').length;
const leadsPorOrigen = leads.reduce((acc, l) => {
  const o = l.origen || 'desconocido';
  acc[o] = (acc[o] || 0) + 1;
  return acc;
}, {});

// Posts stats from G54
const totalPosts = posts.length;
const postsPorPlataforma = posts.reduce((acc, p) => {
  const pl = p.platform || 'sin_plataforma';
  acc[pl] = (acc[pl] || 0) + 1;
  return acc;
}, {});

// FB insights summary
const fbResumen = fbPosts.map(p => {
  const ins = p.insights?.data || [];
  const reach = ins.find(i => i.name === 'reach')?.values?.[0]?.value || 0;
  const impressions = ins.find(i => i.name === 'impressions')?.values?.[0]?.value || 0;
  const engaged = ins.find(i => i.name === 'engaged_users')?.values?.[0]?.value || 0;
  const clicks = ins.find(i => i.name === 'post_clicks')?.values?.[0]?.value || 0;
  return { id: p.id, mensaje: (p.message || '').slice(0, 100), reach, impressions, engaged, clicks };
});

// IG insights summary
const igResumen = igMedia.map(m => ({
  id: m.id,
  caption: (m.caption || '').slice(0, 100),
  likes: m.like_count || 0,
  comments: m.comments_count || 0,
  tipo: m.media_type || 'IMAGE'
}));

// Metricas from G54 (if available)
const metricasResumen = metricas.slice(0, 10).map(m => ({
  fecha: m.fecha || m.created_at || '',
  plataforma: m.platform || '',
  alcance: m.reach || 0,
  engagement: m.engagement || 0,
  clicks: m.clicks || 0
}));

// KPIs from strategy
const kpis = estrategia.kpis || [];
const objetivo = estrategia.objetivo || '';
const audiencia = estrategia.audiencia || '';
const pilares = estrategia.pilares || [];

const periodoAnalisis = config.DIAS_ANALISIS || 30;
const nombreEmpresa = empresa.name || 'la empresa';

const contextoAnalytics = `EMPRESA: ${nombreEmpresa}
OBJETIVO ESTRATÉGICO: ${objetivo}
AUDIENCIA: ${audiencia}
PILARES DE CONTENIDO: ${Array.isArray(pilares) ? pilares.join(', ') : pilares}
KPIs DEFINIDOS: ${Array.isArray(kpis) ? kpis.join(', ') : kpis}
PERÍODO: últimos ${periodoAnalisis} días

--- DATOS DE CONTENIDO (G54) ---
Total posts publicados: ${totalPosts}
Distribución por plataforma: ${JSON.stringify(postsPorPlataforma)}

--- MÉTRICAS REDES SOCIALES (Graph API) ---
FACEBOOK (últimos 10 posts):
${fbResumen.length > 0 ? JSON.stringify(fbResumen, null, 2) : 'Sin datos disponibles (token no configurado)'}

INSTAGRAM (últimos 10 posts):
${igResumen.length > 0 ? JSON.stringify(igResumen, null, 2) : 'Sin datos disponibles (token no configurado)'}

MÉTRICAS HISTÓRICAS G54:
${metricasResumen.length > 0 ? JSON.stringify(metricasResumen, null, 2) : 'Sin métricas guardadas aún'}

--- DATOS DE CONVERSIÓN (G54) ---
Total leads período: ${totalLeads}
Leads calientes: ${leadsCalientes}
Leads tibios: ${leadsTibios}
Leads por origen: ${JSON.stringify(leadsPorOrigen)}
Tasa de calificación: ${totalLeads > 0 ? Math.round((leadsCalientes / totalLeads) * 100) : 0}%`;

return [{ json: {
  contextoAnalytics,
  nombreEmpresa,
  emailEmpresa: (empresa.emails || [])[0] || '',
  totalPosts,
  totalLeads,
  leadsCalientes,
  periodoAnalisis
}}];

const groqRaw = $('🤖 Groq: Analytics AI').item.json;
const texto = groqRaw.choices?.[0]?.message?.content || '';

const get = (label) => {
  const regex = new RegExp(`${label}[:\\s]+([\\s\\S]*?)(?=\\n[A-ZÁÉÍÓÚ\\s]+:|$)`, 'i');
  const match = texto.match(regex);
  return (match?.[1] || '').trim();
};

const reporte = get('REPORTE');
const topContenido = get('TOP CONTENIDO');
const bajoRendimiento = get('BAJO RENDIMIENTO');
const insightsSEO = get('INSIGHTS SEO');
const insightsAEO = get('INSIGHTS AEO');
const insightsGEO = get('INSIGHTS GEO');
const insightsConversion = get('INSIGHTS CONVERSI[ÓO]N');
const recomendaciones = get('RECOMENDACIONES');

const datos = $('🔧 Preparar Datos Analytics').item.json;

return [{ json: {
  reporte,
  topContenido,
  bajoRendimiento,
  insightsSEO,
  insightsAEO,
  insightsGEO,
  insightsConversion,
  recomendaciones,
  texto_completo: texto,
  nombreEmpresa: datos.nombreEmpresa,
  emailEmpresa: datos.emailEmpresa,
  totalPosts: datos.totalPosts,
  totalLeads: datos.totalLeads,
  leadsCalientes: datos.leadsCalientes,
  periodoAnalisis: datos.periodoAnalisis
}}];

const reporte = $('🔍 Parsear Reporte Analytics').item.json;
const config  = $('⚙️ Config Growth54').item.json;

// Detectar métricas numéricas desde los datos preparados
const datos = $('🔧 Preparar Datos Analytics').item.json;

// Intentar extraer engagement promedio de FB insights
let engagement_promedio = 0;
let alcance_total = 0;
let mejor_plataforma = '';
let mejor_tipo_contenido = '';
let keywords_top = [];

try {
  const fbInsights = $('📊 Graph API: FB Insights').item?.json || {};
  const fbPosts = fbInsights.data || [];
  const igInsights = $('📊 Graph API: IG Insights').item?.json || {};
  const igMedia = igInsights.data || [];

  // Alcance total FB
  let alcanceFB = 0;
  let engagedFB = 0;
  fbPosts.forEach(p => {
    const ins = p.insights?.data || [];
    alcanceFB += ins.find(i => i.name === 'reach')?.values?.[0]?.value || 0;
    engagedFB += ins.find(i => i.name === 'engaged_users')?.values?.[0]?.value || 0;
  });

  // Engagement IG
  let totalLikesIG = 0;
  let totalCommentsIG = 0;
  igMedia.forEach(m => {
    totalLikesIG += m.like_count || 0;
    totalCommentsIG += m.comments_count || 0;
  });

  alcance_total = alcanceFB;
  const totalPosts = (fbPosts.length + igMedia.length) || 1;
  engagement_promedio = Math.round((engagedFB + totalLikesIG + totalCommentsIG) / totalPosts);

  mejor_plataforma = alcanceFB > (totalLikesIG + totalCommentsIG) ? 'Facebook' : 'Instagram';
} catch(e) { /* sin datos de Graph API disponibles */ }

// Extraer keywords_top del reporte si las menciona
try {
  const texto = reporte.texto_completo || '';
  const kwMatch = texto.match(/keywords?[:\s]+([^\n.]+)/i);
  if (kwMatch) {
    keywords_top = kwMatch[1].split(/[,;]/).map(k => k.trim()).filter(Boolean).slice(0, 5);
  }
} catch(e) {}

// Mejor tipo de contenido desde top contenido
try {
  const top = reporte.topContenido || '';
  if (top.toLowerCase().includes('video') || top.toLowerCase().includes('reel')) {
    mejor_tipo_contenido = 'video';
  } else if (top.toLowerCase().includes('carrusel') || top.toLowerCase().includes('carousel')) {
    mejor_tipo_contenido = 'carrusel';
  } else if (top.toLowerCase().includes('imagen') || top.toLowerCase().includes('foto')) {
    mejor_tipo_contenido = 'imagen';
  } else {
    mejor_tipo_contenido = 'post_texto';
  }
} catch(e) {}

return [{
  json: {
    company_id: config.G54_COMPANY_ID || 1,
    periodo: $now.toFormat('yyyy-MM-dd'),
    tipo: 'semanal',
    metricas: {
      posts_publicados: reporte.totalPosts || 0,
      engagement_promedio: engagement_promedio,
      alcance_total: alcance_total,
      leads_generados: reporte.totalLeads || 0,
      mejor_plataforma: mejor_plataforma,
      mejor_tipo_contenido: mejor_tipo_contenido,
      keywords_top: keywords_top,
      resumen_rendimiento: reporte.texto_completo || reporte.reporte || ''
    }
  }
}];

